args.sparql:
SELECT DISTINCT ?spouse ?spouseLabel ?father ?fatherLabel WHERE {
  dbr:Anne_Woodville (dbo:spouse|dbp:spouse) ?spouse .
  OPTIONAL {
    ?spouse (dbo:father|dbp:father) ?father .
    OPTIONAL { ?father rdfs:label ?fatherLabel . FILTER(LANG(?fatherLabel) = "en") }
  }
  OPTIONAL { ?spouse rdfs:label ?spouseLabel . FILTER(LANG(?spouseLabel) = "en") }
}

SELECT DISTINCT ?father ?fatherLabel ?spouse ?spouseLabel WHERE {
  dbr:Anne_Woodville (dbo:spouse|dbp:spouse) ?spouse .
  {
    ?spouse (dbo:father|dbp:father|dbo:parent|dbp:parent) ?father .
  } UNION {
    ?father (dbo:child|dbp:children|dbp:child|dbp:issue) ?spouse .
  }
  OPTIONAL { ?father rdfs:label ?fatherLabel FILTER(LANG(?fatherLabel) = "en") }
  OPTIONAL { ?spouse rdfs:label ?spouseLabel FILTER(LANG(?spouseLabel) = "en") }
}

SELECT DISTINCT ?person ?genderProp ?genderValue WHERE {
  VALUES ?person { <http://dbpedia.org/resource/Henry_Bourchier,_1st_Earl_of_Essex> <http://dbpedia.org/resource/Edmund_Grey,_1st_Earl_of_Kent> <http://dbpedia.org/resource/Lady_Katherine_Percy> <http://dbpedia.org/resource/Isabel_of_Cambridge,_Countess_of_Essex> }
  ?person ?genderProp ?genderValue .
  FILTER(?genderProp IN (dbo:gender, dbp:gender, foaf:gender))
}

SELECT DISTINCT ?father ?fatherLabel ?spouse ?spouseLabel WHERE {
  dbr:Anne_Woodville (dbo:spouse|dbp:spouse) ?spouse .
  ?spouse dbo:abstract ?abs . FILTER(LANG(?abs) = "en")
  ?father rdfs:label ?fatherLabel . FILTER(LANG(?fatherLabel) = "en")
  FILTER(regex(str(?fatherLabel), "Edmund Grey", "i") && regex(str(?abs), "Edmund Grey", "i"))
  OPTIONAL { ?spouse rdfs:label ?spouseLabel . FILTER(LANG(?spouseLabel) = "en") }
}

SELECT DISTINCT ?father ?fatherLabel WHERE {
  dbr:Anne_Woodville (dbo:spouse|dbp:spouse) ?spouse .
  {
    ?spouse (dbo:father|dbp:father|dbo:parent|dbp:parent) ?father .
  } UNION {
    ?father (dbo:child|dbp:children|dbp:child|dbp:issue) ?spouse .
  } UNION {
    ?spouse dbo:abstract ?abs . FILTER(LANG(?abs) = "en") .
    FILTER(regex(str(?abs), "Edmund Grey", "i")) .
    BIND(<http://dbpedia.org/resource/Edmund_Grey,_1st_Earl_of_Kent> AS ?father)
  }
  OPTIONAL { ?father rdfs:label ?fatherLabel . FILTER(LANG(?fatherLabel) = "en") }
  FILTER(!bound(?fatherLabel) || !regex(str(?fatherLabel), "(^Lady )|(Countess)|(Isabel)", "i"))
}

SELECT DISTINCT ?father ?fatherLabel WHERE {
  dbr:Anne_Woodville (dbo:spouse|dbp:spouse) ?spouse .
  {
    ?spouse (dbo:father|dbp:father|dbo:parent|dbp:parent) ?father .
  } UNION {
    ?father (dbo:child|dbp:children|dbp:child|dbp:issue) ?spouse .
  } UNION {
    ?spouse dbo:abstract ?abs . FILTER(LANG(?abs) = "en") .
    FILTER(regex(str(?abs), "Edmund Grey", "i")) .
    BIND(<http://dbpedia.org/resource/Edmund_Grey,_1st_Earl_of_Kent> AS ?father)
  }
  OPTIONAL { ?father rdfs:label ?fatherLabel . FILTER(LANG(?fatherLabel) = "en") }
  FILTER(!bound(?fatherLabel) || !regex(str(?fatherLabel), "(^Lady )|(Countess)|(Isabel)", "i"))
}

