PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?father ?fatherLabel WHERE {
  dbr:Anne_Woodville(dbo:spouse | dbp:spouse) ?spouse .
  {
    ?spouse(dbo:father | dbp:father | dbo:parent | dbp:parent) ?father .
  } UNION {
    ?father(dbo:child | dbp:children | dbp:child | dbp:issue) ?spouse .
  } UNION {
    ?spouse dbo:abstract ?abs .
    FILTER(LANG(?abs) = "en")
    .
    FILTER(regex(str(?abs) , "Edmund Grey" , "i"))
    .
    BIND(<http://dbpedia.org/resource/Edmund_Grey,_1st_Earl_of_Kent> AS ?father)
  }
  OPTIONAL {
    ?father rdfs:label ?fatherLabel .
    FILTER(LANG(?fatherLabel) = "en")
  }
  FILTER(! bound(?fatherLabel) || ! regex(str(?fatherLabel) , "(^Lady )|(Countess)|(Isabel)" , "i"))
}

